"""Grade records."""


class Grade:
    def __init__(self, student, score):
        self.student = student
        self.score = score

    def __repr__(self):
        return "Grade(%r, %r)" % (self.student, self.score)


ROWS = [('ben', 35), ('dev', 21), ('ana', 29), ('ben', 42), ('ben', 27), ('ben', 56)]


def load_grades():
    """Yield the stored grades one at a time."""
    for student, score in ROWS:
        yield Grade(student, score)

