"""A book of grades with a cached total."""


class GradeBook:
    def __init__(self):
        self._grades = []
        self._total = None

    def add(self, grade):
        """Add one grade to the book."""
        self._grades.append(grade)

    def total(self):
        """Return the total score of the grades in the book."""
        if self._total is None:
            self._total = sum(x.score for x in self._grades)
        return self._total

    def count(self):
        """Return how many grades the book holds."""
        return len(self._grades)

